package com.tihai.controller;
import com.tihai.utils.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import org.springframework.test.util.ReflectionTestUtils;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.io.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class SigninAutomationTest {
 @TempDir Path temp;
 class Bridge implements ExamBrowserSession {final BlockingQueue<Map<String,Object>> events=new LinkedBlockingQueue<>();int starts;boolean hold,unknown;public void send(Map<String,Object> c){starts++;Map<String,Object> e=new HashMap<>();e.put("event",hold?"verification":unknown?"uncertain":"completed");e.put("message",hold?"请完成安全验证":"平台结果");events.add(e);}public Map<String,Object> read()throws IOException{try{return events.take();}catch(InterruptedException e){throw new IOException("interrupted");}}public void close(){}}
 class Fixture extends SigninController implements AutoCloseable {SigninCatalog fakeCatalog=mock(SigninCatalog.class);SigninStore fakeStore=new SigninStore(temp);SecurityAlertHub hub=new SecurityAlertHub();Bridge bridge=new Bridge();SigninCatalog.Entry e=new SigninCatalog.Entry();String preflight="ready";int launches;
  Fixture()throws Exception{e.id="fixture-sign";e.activeId="100";e.courseKey="course-one";e.courseId="10";e.clazzId="20";e.kind="normal";e.ongoing=true;e.title="Fixture attendance";e.course="Fixture course";e.account="fixture-account";when(fakeCatalog.entry(e.id)).thenReturn(e);Map<String,Object> item=new HashMap<>();item.put("id",e.id);item.put("kind","normal");item.put("courseKey",e.courseKey);item.put("ongoing",true);Map<String,Object> data=new HashMap<>();data.put("items",Arrays.asList(item));data.put("courses",Arrays.asList(Collections.singletonMap("id",e.courseKey)));when(fakeCatalog.list()).thenReturn(data);ReflectionTestUtils.setField(this,"catalog",fakeCatalog);ReflectionTestUtils.setField(this,"store",fakeStore);ReflectionTestUtils.setField(this,"security",hub);}
  @Override protected ExamBrowserSession openBrowser(String id){launches++;return bridge;}@Override protected Map<String,Object> init(Job j){return Collections.singletonMap("op","init");}@Override protected String preflight(SigninCatalog.Entry e){return preflight;}
  void waitFor(String state)throws Exception{long end=System.currentTimeMillis()+4000;while(System.currentTimeMillis()<end){Map<String,Object> r=fakeStore.record(e.id);if(r!=null&&state.equals(r.get("state")))return;Thread.sleep(10);}throw new AssertionError("state "+state);}
  public void close(){shutdown();}
 }
 @Test void disabledOrUnselectedPolicyNeverStartsSigning()throws Exception{try(Fixture f=new Fixture()){f.autoPoll();assertEquals(0,f.launches);f.fakeStore.settings(true,Arrays.asList("different-course"));f.autoPoll();assertEquals(0,f.launches);assertNull(f.fakeStore.record(f.e.id));}}
 @Test void selectedOrdinarySignRunsOnceAndPersistsReceipt()throws Exception{try(Fixture f=new Fixture()){f.fakeStore.settings(true,Arrays.asList(f.e.courseKey));f.autoPoll();f.waitFor("completed");f.autoPoll();assertEquals(1,f.launches);assertEquals(1,f.bridge.starts);assertEquals("completed",new SigninStore(temp).record(f.e.id).get("state"));}}
 @Test void locationSignCannotBeStartedAsOrdinary()throws Exception{try(Fixture f=new Fixture()){f.e.kind="location";Map<String,Object> body=new HashMap<>();body.put("id",f.e.id);body.put("confirmed",true);assertNotEquals(200,f.start(body).get("code"));assertEquals(0,f.launches);}}
 @Test void preflightPhoneRequirementPreventsBrowserSubmission()throws Exception{try(Fixture f=new Fixture()){f.preflight="phone_required";f.fakeStore.settings(true,Arrays.asList(f.e.courseKey));f.autoPoll();f.waitFor("phone_required");assertEquals(0,f.launches);}}
 @Test void manualSignRequiresConfirmationAndUnknownResultIsNeverRetried()throws Exception{try(Fixture f=new Fixture()){assertNotEquals(200,f.start(Collections.singletonMap("id",f.e.id)).get("code"));f.bridge.unknown=true;Map<String,Object> body=new HashMap<>();body.put("id",f.e.id);body.put("confirmed",true);assertEquals(200,f.start(body).get("code"));f.waitFor("uncertain");assertNotEquals(200,f.start(body).get("code"));assertEquals(1,f.bridge.starts);}}
 @Test void securityVerificationRaisesPopupEventAndCanBeStopped()throws Exception{try(Fixture f=new Fixture()){f.bridge.hold=true;Map<String,Object> body=new HashMap<>();body.put("id",f.e.id);body.put("confirmed",true);f.start(body);f.waitFor("verification");assertEquals(1,f.hub.snapshot().size());assertEquals(200,f.stop(Collections.singletonMap("id",f.e.id)).get("code"));f.waitFor("stopped");}}
}
